stage.css:
.panel{position:absolute;box-sizing:border-box}
#code .ln{font-family:'JetBrains Mono',monospace;font-size:11.5px;line-height:24px;white-space:pre;padding:0 6px;border-radius:4px;color:var(--muted)}
#code .ln.on{background:rgba(255,204,102,.18);color:var(--text)}
#log div,#results div{font-size:11px;line-height:16px;white-space:nowrap;overflow:hidden}
#log .lg{color:var(--gold)}
#log .jr{color:var(--muted)}
#results div{color:var(--green)}
.slotbox{position:absolute;width:125px;height:72px;border:1px dashed var(--line);border-radius:10px}
.chip{position:absolute;width:118px;height:24px;border-radius:12px;font-family:'JetBrains Mono',monospace;font-size:10px;line-height:24px;text-align:center;color:#000}
.dot{position:absolute;width:10px;height:10px;border-radius:50%;background:var(--green);box-shadow:0 0 8px var(--green)}
.gap{position:absolute;font-size:12px}
#retbd div{font-size:11px;line-height:17px}

stage.script:
const LINES=["export const meta = {","  name: 'review-changes',","  phases: [{title:'Review'},{title:'Verify'}] }","phase('Review')","const out = await pipeline(DIMS,","  d => agent(d.prompt, {label:'review:'+d.key})","  r => agent(check(r), {phase:'Verify'}))","log(`${out.length} reviewed`)","return { confirmed: out.filter(v => v.real) }"];
const code=$('#code');LINES.forEach(l=>{const d=document.createElement('div');d.className='ln';d.textContent=l;code.appendChild(d)});
const lines=$$('#code .ln');
const layer=$('#layer');
const SX=[430,565],SY=[215,295];
for(let k=0;k<4;k++){const b=document.createElement('div');b.className='slotbox';b.style.left=SX[k%2]+'px';b.style.top=SY[k>>1]+'px';layer.appendChild(b)}
const KEYS=['bugs','perf','security','style','docs','tests'];
const RD=[3.2,2.6,4.0,3.0,3.6,2.8].map(x=>x*1.6),VD=[1.8,2.2,1.6,2.0,1.9,2.1].map(x=>x*1.5);
const T0=B[1]+1.2,CAP=4;
const jobs=[];KEYS.forEach((k,i)=>jobs.push({label:'review:'+k,kind:'r',i,q:T0+i*0.45,d:RD[i]}));
(function(){const slots=[null,null,null,null];let queue=[];let pending=jobs.slice();for(let n=0;n<1200;n++){const t=n*0.05;for(let k=0;k<CAP;k++){const j=slots[k];if(j&&t>=j.f){slots[k]=null;if(j.kind==='r'){const v={label:'verify:'+KEYS[j.i],kind:'v',i:j.i,q:t,d:VD[j.i]};jobs.push(v);pending.push(v)}}}
pending=pending.filter(j=>{if(j.q<=t){queue.push(j);return false}return true});
for(let k=0;k<CAP;k++){if(!slots[k]&&queue.length){const j=queue.shift();j.s=t;j.f=t+j.d;j.slot=k;slots[k]=j}}}})();
const chips=jobs.map(j=>{const c=document.createElement('div');c.className='chip';c.textContent=j.label;c.style.background=j.kind==='r'?'var(--sky)':'var(--peri)';layer.appendChild(c);const d=document.createElement('div');d.className='dot';layer.appendChild(d);return {c,d}});
const events=[];jobs.forEach(j=>{events.push({t:j.s,txt:'started '+j.label});events.push({t:j.f,txt:'result  '+j.label})});events.sort((a,b)=>a.t-b.t);
const LOGT=B[3]+0.8;
const tagdefs=[['#script','NOT SHOWN','var(--red)'],['#logp','NOT SHOWN','var(--red)'],['#res','NOT SHOWN','var(--red)'],['#ret','NOT SHOWN','var(--red)'],['#queue','PATTERN BUFFER','var(--green)'],['#slots','PADS','var(--green)'],['#lead','BRIEFING ROOM','var(--green)']];
const tags=tagdefs.map(([sel,txt,col])=>{const el=$(sel);const g=document.createElement('div');g.className='gap';g.innerHTML=tag(txt,col);g.style.left=(parseFloat(el.style.left)+parseFloat(el.style.width)-150)+'px';g.style.top=(parseFloat(el.style.top)+4)+'px';g.style.width='146px';g.style.textAlign='right';layer.appendChild(g);return g});
function render(t){
 const hl=t<B[1]?[0,1,2]:t<B[2]?[3,5]:t<B[3]?[4,5,6]:t<B[4]?[7]:t<B[5]?[8]:[];
 lines.forEach((l,i)=>l.classList.toggle('on',hl.includes(i)));
 const queued=jobs.filter(j=>t>=j.q&&t<j.s);
 jobs.forEach((j,n)=>{const {c,d}=chips[n];let x,y,o=1;
  if(t<j.q){o=0;x=440;y=55}
  else if(t<j.s){const qi=queued.indexOf(j);x=432+(qi%2)*130;y=60+Math.floor(qi/2)*30}
  else {o=t<j.f?1:0;x=SX[j.slot]+3;y=SY[j.slot]+24}
  c.style.left=x+'px';c.style.top=y+'px';c.style.opacity=o;
  const fp=clamp((t-j.f)/0.9,0,1);
  if(t>=j.f&&fp<1){const sx=SX[j.slot]+60,sy=SY[j.slot]+36,ex=380,ey=j.kind==='r'?165:189;d.style.opacity=1;d.style.left=(sx+(ex-sx)*fp)+'px';d.style.top=(sy+(ey-sy)*fp-Math.sin(fp*Math.PI)*40)+'px'}else d.style.opacity=0;
 });
 const done=jobs.filter(j=>t>=j.f+0.9).sort((a,b)=>a.f-b.f);
 $('#results').innerHTML=done.map(j=>`<div>${j.label} → ${j.kind==='r'?'{findings:'+((j.i*7)%4+1)+'}':'{real:'+(j.i%3?'true':'false')+'}'}</div>`).join('');
 const ev=events.filter(e=>e.t<=t).slice(-5).map(e=>`<div class="jr">journal · ${e.txt}</div>`);
 if(t>=LOGT){ev.shift();ev.push('<div class="lg">log · 6 reviewed</div>')}
 $('#log').innerHTML=ev.join('');
 const rp=p(t,B[4]+0.3,B[4]+1.6);
 $('#retbd').innerHTML=rp>0?`<div>{ confirmed: [4 findings] }</div><div style="color:var(--muted)">412k tokens · 180 tool calls · 6m 12s</div>`:'';
 $('#ret').style.opacity=0.35+0.65*rp;
 $('#leadbd').innerHTML=t>=B[4]+1.6?'<span style="color:var(--orange)">new turn: takes the result</span>':'carrying on with other work…';
 tags.forEach(g=>g.style.opacity=p(t,B[5]+0.3,B[5]+1.3));
}
